UPDATE point_wallet_tbl AS w INNER JOIN event_reward_tbl AS r ON r.reward_id = #{rewardId}
SET w.point_balance = w.point_balance + r.reward_point
WHERE w.user_id = #{userId}

UPDATE event_challenge_user_tbl AS ecu INNER JOIN event_reward_tbl AS er ON er.reward_id = #{rewardId}
   SET ecu.exp = ecu.exp + er.reward_exp,
       ecu.updated_at = NOW()
 WHERE ecu.user_id = #{userId}
   AND ecu.status = 'PROCESS'

