SELECT COUNT(*)
FROM (
         SELECT event_id, user_id FROM event_participation_tbl
         WHERE event_id = #{eventId} AND user_id = #{userId}
         UNION ALL
         SELECT event_id, user_id FROM event_attendance_tbl
         WHERE event_id = #{eventId} AND user_id = #{userId}
     ) AS total_part

SELECT COUNT(*)
FROM event_reward_receive_tbl
WHERE event_id = #{eventId}
  AND reward_id = #{rewardId}
  AND user_id = #{userId}
